export const PDF_DEFAULT_CONFIG = {
  scale: 1.5,
  format: 'a4' as const,
  orientation: 'landscape' as const,
  margin: 0,
  preserveLinks: true,
  quality: 1,
  imageFormat: 'JPEG' as const,
  compression: true,
};
